function ConversationsPage({user}) {
  const canCreate=user.role!=='SELLER';const [items,setItems]=useState([]);const [contacts,setContacts]=useState([]);const [selected,setSelected]=useState(null);const [messages,setMessages]=useState([]);const [editing,setEditing]=useState(null);const [error,setError]=useState('');const [busy,setBusy]=useState(false);
  const load=()=>Promise.all([api('/conversations'),canCreate?api('/users'):Promise.resolve({items:[]})]).then(([conversations,users])=>{setItems(conversations.items||[]);setContacts((users.items||[]).filter(item=>item.status==='ACTIVE'&&item.id!==user.id));setError('')}).catch(reason=>setError(reason.message));useEffect(()=>{load();},[]);
  const open=async item=>{setSelected(item);try{const data=await api(`/conversations/${item.id}/messages`);setMessages(data.items||[])}catch(reason){setError(reason.message)}};
  const save=async event=>{event.preventDefault();setBusy(true);const form=new FormData(event.currentTarget);try{await api(editing.id?`/conversations/${editing.id}`:'/conversations',{method:editing.id?'PATCH':'POST',body:JSON.stringify({type:form.get('type'),name:form.get('name'),memberIds:form.getAll('memberIds')})});setEditing(null);load();}catch(reason){setError(reason.message)}finally{setBusy(false)}};
  const send=async event=>{event.preventDefault();const form=new FormData(event.currentTarget);const message=form.get('message');if(!message.trim())return;try{await api(`/conversations/${selected.id}/messages`,{method:'POST',body:JSON.stringify({message})});form.reset();open(selected);}catch(reason){setError(reason.message)}};
  const remove=async item=>{if(!confirm(`Excluir a conversa ${item.name||'selecionada'} e suas mensagens?`))return;try{await api(`/conversations/${item.id}`,{method:'DELETE'});if(selected?.id===item.id){setSelected(null);setMessages([])}load();}catch(reason){setError(reason.message)}};
  return <section className="crud-page"><div className="crud-toolbar"><div><h2>Mensagens</h2><p>Conversas de equipe, comunicados e acompanhamento operacional.</p></div>{canCreate&&<button className="primary-button" onClick={()=>setEditing({type:'GROUP'})}><Plus size={18}/>Nova conversa</button>}</div>{error&&<div className="api-error">{error}<button onClick={load}>Tentar novamente</button></div>}<div className="messages-layout"><aside className="conversation-list">{items.map(item=><button className={selected?.id===item.id?'active':''} key={item.id} onClick={()=>open(item)}><MessageCircle size={18}/><span><b>{item.name||({DIRECT:'Conversa direta',GROUP:'Grupo',ANNOUNCEMENT:'Comunicado'})[item.type]}</b><small>{item.last_message||'Sem mensagens'}</small></span></button>)}{!items.length&&<div className="records-empty">Nenhuma conversa disponível.</div>}</aside><section className="message-thread">{selected?<><header><div><h3>{selected.name||'Conversa'}</h3><span>{selected.type}</span></div>{(selected.created_by===user.id||['SUPER_ADMIN','MANAGER'].includes(user.role))&&<div className="row-actions"><button onClick={()=>setEditing(selected)}><Pencil size={17}/></button><button className="danger-action" onClick={()=>remove(selected)}><Trash2 size={17}/></button></div>}</header><div className="message-stream">{messages.map(item=><div className={item.sender_id===user.id?'own':''} key={item.id}><b>{item.sender_name}</b><p>{item.message}</p><small>{new Date(item.created_at).toLocaleString('pt-BR')}</small></div>)}{!messages.length&&<div className="records-empty">Inicie esta conversa.</div>}</div><form className="message-compose" onSubmit={send}><input name="message" placeholder="Escreva uma mensagem..." autoComplete="off"/><button className="primary-button" title="Enviar"><Send size={18}/></button></form></>:<DashboardEmpty icon={<MessageCircle size={26}/>} title="Selecione uma conversa" text="As mensagens da conversa escolhida aparecerão aqui."/>}</section></div>{editing&&<CrudDialog title={editing.id?'Editar conversa':'Nova conversa'} subtitle="Defina o tipo, nome e participantes." close={()=>setEditing(null)} onSubmit={save} busy={busy}><label>Tipo<select name="type" defaultValue={editing.type||'GROUP'} disabled={!!editing.id}><option value="DIRECT">Direta</option><option value="GROUP">Grupo</option><option value="ANNOUNCEMENT">Comunicado</option></select></label><label>Nome<input name="name" defaultValue={editing.name||''} placeholder="Ex.: Operação Centro" required/></label><label className="wide-field">Participantes<select name="memberIds" multiple size="7" defaultValue={[]} required>{contacts.map(item=><option key={item.id} value={item.id}>{item.name} · {item.role}</option>)}</select></label></CrudDialog>}</section>;
}

function RankingPage({items}) { return <section className="operational-page"><div className="operational-tools"><div><h2>Ranking do período</h2><p>Ordenado pelo atingimento consolidado.</p></div></div><div className="ranking-board">{items.map((item,index)=><div key={item.id||index}><strong>{String(index+1).padStart(2,'0')}</strong><div className="avatar avatar-main">{item.name.slice(0,2).toUpperCase()}</div><span><b>{item.name}</b><small>{item.team_name||'Sem mesa'}</small></span><em>{Math.round(item.achievement)}%</em></div>)}</div></section>; }
function ReportsPage({user}) {
  const [tab,setTab]=useState('EXPORTS');const [periods,setPeriods]=useState([]);const [periodId,setPeriodId]=useState('');const [rankingItems,setRankingItems]=useState([]);const [error,setError]=useState('');
  const loadPeriods=()=>api('/periods').then(data=>{const items=data.items||[];setPeriods(items);setPeriodId(current=>current||items.find(item=>item.status==='OPEN')?.id||items[0]?.id||'');}).catch(reason=>setError(reason.message));
  useEffect(()=>{loadPeriods();},[]);useEffect(()=>{if(!periodId){setRankingItems([]);return}api(`/dashboard?periodId=${periodId}`).then(data=>{setRankingItems(data.ranking||[]);setError('')}).catch(reason=>setError(reason.message));},[periodId]);
  const selectedPeriod=periods.find(item=>item.id===periodId);
  const reportPath=extension=>`/reports/export.${extension}${periodId?`?periodId=${encodeURIComponent(periodId)}`:''}`;
  return <section className="reports-hub"><div className="reports-hero"><div><span>CENTRAL INTELIGENTE</span><h2>Relatórios e desempenho</h2><p>Dados, ciclos comerciais e ranking conectados em uma única visão.</p></div><div className="reports-period-picker"><CalendarDays size={18}/><label>Período<select value={periodId} onChange={event=>setPeriodId(event.target.value)}>{periods.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div></div><nav className="reports-tabs" aria-label="Seções de relatórios">{[['EXPORTS',Download,'Exportações'],['RANKING',Trophy,'Ranking'],['PERIODS',CalendarDays,'Períodos']].map(([value,Icon,label])=><button key={value} className={tab===value?'active':''} onClick={()=>setTab(value)}><Icon size={17}/>{label}</button>)}</nav>{error&&<div className="api-error">{error}<button onClick={loadPeriods}>Tentar novamente</button></div>}{tab==='EXPORTS'&&<div className="reports-section"><div className="reports-section-title"><div><h3>Arquivos para análise</h3><p>{selectedPeriod?`Visão operacional de ${selectedPeriod.name}.`:'Selecione um período para contextualizar os dados.'}</p></div><span className="reports-live"><i/>Dados sincronizados</span></div><div className="report-options"><a href={`/api${reportPath('xlsx')}`} onClick={event=>downloadReport(event,reportPath('xlsx'))}><FileSpreadsheet size={22}/><b>Excel</b><span>Base detalhada do período</span><Download size={17}/></a><a href={`/api${reportPath('csv')}`} onClick={event=>downloadReport(event,reportPath('csv'))}><ClipboardList size={22}/><b>CSV</b><span>Dados para integração</span><Download size={17}/></a><a href={`/api${reportPath('pdf')}`} onClick={event=>downloadReport(event,reportPath('pdf'))}><BarChart3 size={22}/><b>PDF</b><span>Relatório executivo</span><Download size={17}/></a></div></div>}{tab==='RANKING'&&<div className="reports-section"><div className="reports-section-title"><div><h3>Ranking do período</h3><p>Ordenado automaticamente pelo atingimento consolidado.</p></div><b className="reports-count">{rankingItems.length} vendedores</b></div><div className="ranking-board">{rankingItems.map((item,index)=><div key={item.id||index}><strong>{String(index+1).padStart(2,'0')}</strong><div className="avatar avatar-main">{item.name.slice(0,2).toUpperCase()}</div><span><b>{item.name}</b><small>{item.team_name||'Sem mesa'}</small></span><em>{Math.round(item.achievement)}%</em></div>)}{!rankingItems.length&&<DashboardEmpty icon={<Trophy size={25}/>} title="Ranking aguardando dados" text="Metas e resultados deste período aparecerão aqui automaticamente."/>}</div></div>}{tab==='PERIODS'&&<div className="reports-section"><PeriodsPage user={user} onChange={loadPeriods}/></div>}</section>;
}
async function downloadReport(event,path) { event.preventDefault();const token=localStorage.getItem('rv_token');const response=await fetch(`/api${path}`,{headers:{Authorization:`Bearer ${token}`}});if(!response.ok)return;const blob=await response.blob();const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=response.headers.get('content-disposition')?.match(/filename="?([^";]+)"?/)?.[1]||'relatorio';link.click();URL.revokeObjectURL(link.href); }
function AlertsPage({items}) { return <section className="operational-page"><div className="operational-tools"><div><h2>Alertas da mesa</h2><p>Pontos que exigem atenção imediata.</p></div></div><div className="alerts-list">{items.map((item,index)=><div key={index}><AlertTriangle size={19}/><span><b>{item.level==='CRITICAL'?'Crítico':'Atenção'}</b>{item.message}</span></div>)}{!items.length&&<div><CheckCircle2 size={19}/><span><b>Operação estável</b>Nenhum alerta crítico no período.</span></div>}</div></section>; }

function ActionsPage({user}) {
  const [data,setData]=useState({items:[],summary:{}});
  const [filter,setFilter]=useState('ALL');
  const [selected,setSelected]=useState(null);
  const [creating,setCreating]=useState(false);
  const [editing,setEditing]=useState(null);
  const [error,setError]=useState('');
  const load=()=>api('/actions').then(setData).catch(reason=>setError(reason.message));
  useEffect(()=>{load();},[]);
  const items=data.items.filter(item=>filter==='ALL'||item.status===filter);
  const heading=user.role==='SELLER'?'Minhas Ações':user.role==='SUPERVISOR'?'Ações da Minha Mesa':'Ações da Operação';
  return <div className="actions-module">
    <div className="actions-toolbar"><div><h2>{heading}</h2><p>Do diagnóstico à execução, com responsabilidade e resultado mensurável.</p></div>{['SUPER_ADMIN','MANAGER'].includes(user.role)&&<button className="primary-button" onClick={()=>setCreating(true)}><Plus size={18}/>Nova ação</button>}</div>
    {error&&<div className="api-error">{error}<button onClick={load}>Tentar novamente</button></div>}
    <section className="action-kpis">
      <ActionKpi label="Ativas" value={data.summary.active||0} tone="blue"/>
      <ActionKpi label={user.role==='SELLER'?'Em execução':'Em andamento'} value={data.summary.inProgress||0} tone="teal"/>
      <ActionKpi label="Em risco" value={data.summary.atRisk||0} tone="orange"/>
      <ActionKpi label="Concluídas" value={data.summary.completed||0} tone="green"/>
      <ActionKpi label="Atrasadas" value={data.summary.overdue||0} tone="red"/>
    </section>
    <div className="action-filters"><SlidersHorizontal size={17}/><button className={filter==='ALL'?'active':''} onClick={()=>setFilter('ALL')}>Todas</button><button className={filter==='IN_PROGRESS'?'active':''} onClick={()=>setFilter('IN_PROGRESS')}>Em andamento</button><button className={filter==='AT_RISK'?'active':''} onClick={()=>setFilter('AT_RISK')}>Em risco</button><button className={filter==='COMPLETED'?'active':''} onClick={()=>setFilter('COMPLETED')}>Concluídas</button></div>
    <section className="action-list">{items.map(item=><div className="action-card-wrap" key={item.id}><ActionCard item={item} user={user} onClick={()=>setSelected(item.id)}/>{['SUPER_ADMIN','MANAGER'].includes(user.role)&&<button className="action-edit-button" title="Gerenciar ação" onClick={()=>setEditing(item)}><Pencil size={16}/></button>}</div>)}{!items.length&&<div className="action-empty"><ClipboardList size={28}/><b>Nenhuma ação neste filtro</b><span>As ações vinculadas ao seu perfil aparecerão aqui.</span></div>}</section>
    {creating&&<CreateAction close={()=>setCreating(false)} onCreated={()=>{setCreating(false);load();}}/>}
    {editing&&<EditAction item={editing} close={()=>setEditing(null)} onChanged={()=>{setEditing(null);load();}}/>}
    {selected&&<ActionDetail actionId={selected} user={user} close={()=>setSelected(null)} onChange={load}/>} 
  </div>;
}

function ActionKpi({label,value,tone}) { return <article className={`action-kpi ${tone}`}><span>{label}</span><b>{value}</b></article>; }
const actionStatus={DRAFT:'Rascunho',CREATED:'Criada',DISTRIBUTED:'Distribuída',IN_PROGRESS:'Em andamento',AT_RISK:'Em risco',COMPLETED:'Concluída',OVERDUE:'Atrasada',CANCELLED:'Cancelada'};
const actionPriority={LOW:'Baixa',NORMAL:'Normal',HIGH:'Alta',CRITICAL:'Crítica'};
function ActionCard({item,user,onClick}) {
  const target=Number(item.scope_target_value??item.target_value);
  const progress=Number(item.progress_value||0);
  const percent=target?Math.min(100,progress/target*100):0;
  const days=Math.ceil((new Date(item.end_date)-new Date())/86400000);
  return <button className="action-card" onClick={onClick}><div className="action-card-head"><span className={`priority priority-${item.priority.toLowerCase()}`}>{actionPriority[item.priority]}</span><span className={`action-status status-${item.status.toLowerCase()}`}>{actionStatus[item.status]}</span></div><h3>{item.title}</h3><p>{item.indicator_name||'Ação de gestão'}<span>{item.teams||item.period_name||''}</span></p><div className="action-progress-copy"><span>{progress.toLocaleString('pt-BR')} de {target.toLocaleString('pt-BR')}</span><b>{Math.round(percent)}%</b></div><div className="action-progress"><i className={progressClass(percent)} style={{width:`${percent}%`}}/></div><footer><span><CalendarDays size={15}/>{days<0?'Prazo encerrado':days===0?'Encerra hoje':`${days} dias restantes`}</span><span>Ver ação <ChevronRight size={16}/></span></footer></button>;
}

function EditAction({item,close,onChanged}) {
  const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  const submit=async event=>{event.preventDefault();setBusy(true);const form=new FormData(event.currentTarget);try{await api(`/actions/${item.id}`,{method:'PATCH',body:JSON.stringify({title:form.get('title'),description:form.get('description'),priority:form.get('priority'),status:form.get('status'),endDate:form.get('endDate')})});onChanged();}catch(reason){setError(reason.message)}finally{setBusy(false)}};
  const remove=async()=>{if(!confirm('Excluir esta ação e todo o histórico relacionado?'))return;setBusy(true);try{await api(`/actions/${item.id}`,{method:'DELETE'});onChanged();}catch(reason){setError(reason.message);setBusy(false)}};
  return <CrudDialog title="Gerenciar ação" subtitle="Atualize a execução ou remova a intervenção." close={close} onSubmit={submit} busy={busy}><label className="wide-field">Título<input name="title" defaultValue={item.title} required/></label><label>Prioridade<select name="priority" defaultValue={item.priority}>{Object.entries(actionPriority).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label><label>Situação<select name="status" defaultValue={item.status}>{Object.entries(actionStatus).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label><label>Prazo final<input name="endDate" type="date" defaultValue={String(item.end_date).slice(0,10)} required/></label><label className="wide-field">Descrição<textarea name="description" rows="4" defaultValue={item.description||''}/></label>{error&&<p className="form-error wide-field">{error}</p>}<button type="button" className="inline-danger wide-field" onClick={remove} disabled={busy}><Trash2 size={16}/>Excluir ação</button></CrudDialog>;
}

function CreateAction({close,onCreated}) {
  const [options,setOptions]=useState({teams:[],indicators:[],periods:[]});const [error,setError]=useState('');const [busy,setBusy]=useState(false);
  const today=new Date().toISOString().slice(0,10);const ending=new Date(Date.now()+5*86400000).toISOString().slice(0,10);
  useEffect(()=>{Promise.all([api('/teams'),api('/indicators'),api('/periods')]).then(([teams,indicators,periods])=>setOptions({teams:teams.items,indicators:indicators.items,periods:periods.items})).catch(reason=>setError(reason.message));},[]);
  const submit=async event=>{event.preventDefault();setBusy(true);setError('');const form=new FormData(event.currentTarget);try{await api('/actions',{method:'POST',body:JSON.stringify({title:form.get('title'),description:form.get('description'),type:form.get('type'),priority:form.get('priority'),indicatorId:form.get('indicatorId'),periodId:form.get('periodId'),startDate:form.get('startDate'),endDate:form.get('endDate'),targetValue:form.get('targetValue'),expectedResult:form.get('expectedResult'),successIndicator:form.get('successIndicator'),teamIds:form.getAll('teamIds')})});onCreated();}catch(reason){setError(reason.message)}finally{setBusy(false)}};
  return <div className="modal-backdrop" onMouseDown={close}><form className="action-form" onSubmit={submit} onMouseDown={event=>event.stopPropagation()}><header><div><p className="eyebrow">NOVA INTERVENÇÃO</p><h2>Criar ação de gestão</h2><span>Use dados reais sem alterar as metas oficiais.</span></div><button type="button" className="modal-close" onClick={close}><X size={20}/></button></header><div className="action-form-grid"><label className="wide">Título<input name="title" placeholder="Ex.: Recuperação de Centurião" required/></label><label>Tipo<select name="type" defaultValue="RECOVERY"><option value="RECOVERY">Recuperação</option><option value="ACCELERATION">Aceleração</option><option value="CORRECTION">Correção</option><option value="OPPORTUNITY">Oportunidade</option><option value="FOLLOW_UP">Acompanhamento</option><option value="TRAINING">Treinamento</option><option value="CAMPAIGN">Campanha</option><option value="CHALLENGE">Desafio</option></select></label><label>Prioridade<select name="priority" defaultValue="HIGH"><option value="LOW">Baixa</option><option value="NORMAL">Normal</option><option value="HIGH">Alta</option><option value="CRITICAL">Crítica</option></select></label><label className="wide">Descrição<textarea name="description" placeholder="Contexto identificado e orientação para execução"/></label><label>Indicador<select name="indicatorId" required><option value="">Selecione</option>{options.indicators.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Período<select name="periodId" required><option value="">Selecione</option>{options.periods.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Data inicial<input name="startDate" type="date" defaultValue={today} required/></label><label>Data final<input name="endDate" type="date" defaultValue={ending} required/></label><label>Meta da ação<input name="targetValue" type="number" min="0" step="0.01" placeholder="64" required/></label><label>Indicador de sucesso<input name="successIndicator" placeholder="Atingir 85%"/></label><fieldset className="wide"><legend>Mesas responsáveis</legend><div className="team-checks">{options.teams.map(team=><label key={team.id}><input type="checkbox" name="teamIds" value={team.id}/><span>{team.name}</span></label>)}</div></fieldset><label className="wide">Resultado esperado<input name="expectedResult" placeholder="Ex.: elevar a projeção de 68% para 85%"/></label></div>{error&&<p className="form-error">{error}</p>}<footer><button type="button" className="filter-button" onClick={close}>Cancelar</button><button className="primary-button" disabled={busy}><CheckCircle2 size={18}/>{busy?'Criando...':'Criar e direcionar'}</button></footer></form></div>;
}

function ActionDetail({actionId,user,close,onChange}) {
  const [data,setData]=useState(null);const [suggestion,setSuggestion]=useState([]);const [comment,setComment]=useState('');const [error,setError]=useState('');
  const load=()=>api(`/actions/${actionId}`).then(setData).catch(reason=>setError(reason.message));useEffect(()=>{load();},[actionId]);
  const suggest=async()=>{try{const result=await api(`/actions/${actionId}/distribution-suggestion`);setSuggestion(result.items.map(item=>({...item,value:item.suggested})));}catch(reason){setError(reason.message)}};
  const distribute=async()=>{try{await api(`/actions/${actionId}/distribute`,{method:'POST',body:JSON.stringify({allocations:suggestion.map(item=>({userId:item.id,assignedValue:Number(item.value)}))})});setSuggestion([]);load();onChange();}catch(reason){setError(reason.message)}};
  const updateProgress=async(event,target)=>{event.preventDefault();const value=new FormData(event.currentTarget).get('progress');try{await api(`/actions/${actionId}/progress`,{method:'PATCH',body:JSON.stringify({userId:target.user_id,progressValue:value})});load();onChange();}catch(reason){setError(reason.message)}};
  const sendComment=async event=>{event.preventDefault();try{await api(`/actions/${actionId}/comments`,{method:'POST',body:JSON.stringify({comment})});setComment('');load();}catch(reason){setError(reason.message)}};
  return <div className="action-drawer-backdrop" onMouseDown={close}><aside className="action-drawer" onMouseDown={event=>event.stopPropagation()}>{!data?<div className="drawer-loading">{error||'Carregando ação...'}</div>:<><header><div><span className={`priority priority-${data.item.priority.toLowerCase()}`}>{actionPriority[data.item.priority]}</span><h2>{data.item.title}</h2><p>{data.item.description||data.item.expected_result}</p></div><button className="modal-close" onClick={close}><X size={20}/></button></header><div className="drawer-summary"><div><span>Meta da ação</span><b>{actionDetailTarget(data,user).toLocaleString('pt-BR')}</b></div><div><span>Prazo</span><b>{new Date(data.item.end_date).toLocaleDateString('pt-BR')}</b></div><div><span>Status</span><b>{actionStatus[data.item.status]}</b></div></div>{error&&<p className="form-error">{error}</p>}{user.role==='SUPERVISOR'&&!suggestion.length&&<button className="suggest-button" onClick={suggest}><Gauge size={18}/><span><b>Gerar distribuição ponderada</b><small>Gap, performance e capacidade observada</small></span><ChevronRight size={18}/></button>}{suggestion.length>0&&<section className="distribution"><div className="drawer-section-title"><div><h3>Distribuição sugerida</h3><p>Ajuste os valores antes de confirmar.</p></div><b>{suggestion.reduce((sum,item)=>sum+Number(item.value||0),0).toLocaleString('pt-BR')}</b></div>{suggestion.map((item,index)=><label key={item.id}><span>{item.name}<small>{Number(item.target)?`${Math.round(Number(item.achieved)/Number(item.target)*100)}% de atingimento`:'Sem meta oficial'}</small></span><div className="distribution-bar"><i style={{width:`${Math.min(100,Number(item.value)/Math.max(...suggestion.map(row=>Number(row.value)),1)*100)}%`}}/></div><input type="number" min="0" value={item.value} onChange={event=>setSuggestion(current=>current.map((row,rowIndex)=>rowIndex===index?{...row,value:event.target.value}:row))}/></label>)}<button className="primary-button" onClick={distribute}><CheckCircle2 size={18}/>Confirmar distribuição</button></section>}<section className="assignments"><div className="drawer-section-title"><div><h3>Execução individual</h3><p>Metas temporárias vinculadas à ação.</p></div></div>{data.targets.filter(target=>target.user_id).map(target=>{const percent=Number(target.assigned_value)?Number(target.progress_value)/Number(target.assigned_value)*100:0;return <div className="assignment" key={target.id}><div><b>{target.user_name}</b><span>{Number(target.progress_value).toLocaleString('pt-BR')} / {Number(target.assigned_value).toLocaleString('pt-BR')}</span></div><div className="action-progress"><i className={progressClass(percent)} style={{width:`${Math.min(100,percent)}%`}}/></div>{(user.role==='SELLER'||user.role==='SUPERVISOR')&&<form onSubmit={event=>updateProgress(event,target)}><input name="progress" type="number" min="0" step="0.01" defaultValue={Number(target.progress_value)}/><button title="Atualizar progresso"><CheckCircle2 size={17}/></button></form>}</div>})}{!data.targets.some(target=>target.user_id)&&<p className="empty-copy">Aguardando distribuição pelo supervisor.</p>}</section><section className="action-comments"><div className="drawer-section-title"><div><h3>Comentários</h3><p>Alinhamento registrado dentro da ação.</p></div></div>{data.comments.map(item=><div className="comment" key={item.id}><div className="avatar avatar-main">{item.user_name.slice(0,2).toUpperCase()}</div><div><b>{item.user_name}</b><p>{item.comment}</p><span>{new Date(item.created_at).toLocaleString('pt-BR')}</span></div></div>)}<form onSubmit={sendComment}><input value={comment} onChange={event=>setComment(event.target.value)} placeholder="Escreva uma atualização..." required/><button title="Enviar comentário"><Send size={18}/></button></form></section></>}</aside></div>;
}

function actionDetailTarget(data,user) {
  if (user.role==='SELLER') return Number(data.targets.find(target=>target.user_id)?.assigned_value||0);
  if (user.role==='SUPERVISOR') return Number(data.targets.find(target=>!target.user_id)?.target_value||data.item.target_value);
  return Number(data.item.target_value);
}

function DashboardApp({user,onLogout}) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [active, setActive] = useState('Visão geral');
  const [periods, setPeriods] = useState([]);
  const [periodId, setPeriodId] = useState('');
  const [modal, setModal] = useState(null);
  const [notice, setNotice] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [dashboard, setDashboard] = useState(null);
  const [loadError, setLoadError] = useState('');
  const refresh = (selectedPeriod=periodId) => api(`/dashboard${selectedPeriod?`?periodId=${selectedPeriod}`:''}`).then(data => { setDashboard(data); setLoadError(''); }).catch(error => setLoadError(error.message));
  useEffect(() => { Promise.all([api('/dashboard'),api('/periods'),api('/notifications')]).then(([dashboardData,periodData,notificationData])=>{setDashboard(dashboardData);setPeriods(periodData.items||[]);setPeriodId(dashboardData.period?.id||'');setNotifications(notificationData.items||[]);}).catch(error=>setLoadError(error.message)); }, []);
  const unread=notifications.filter(item=>!item.read_at);
  const total = Number(dashboard?.summary?.target || 0);
  const accomplished = Number(dashboard?.summary?.achieved || 0);
  const achievement = Number(dashboard?.summary?.achievement || 0);
  const remaining = Number(dashboard?.summary?.remaining || 0);
  const displayTeams = (dashboard?.teams||[]).map((item,index)=>({name:item.name,lead:`${item.sellers} vendedores`,initials:'RV',target:Number(item.target),achieved:Number(item.achieved),achievement:Number(item.achievement),riskCount:Number(item.riskCount||0),color:teams[index % teams.length].color}));
  const displayRanking = (dashboard?.ranking||[]).map((item,index)=>({name:item.name,initials:item.name.split(' ').slice(0,2).map(p=>p[0]).join(''),team:item.team_name||'Sem mesa',percent:Math.round(item.achievement),tone:['purple','blue','teal','orange','pink'][index%5]}));
  const sidebar = <aside className={`sidebar ${mobileOpen ? 'open' : ''}`}>
    <div className="brand"><div className="brand-mark"><span>R</span><span>V</span></div><div><strong>RV Digital</strong><small>Gestão comercial</small></div><button className="close-menu" onClick={() => setMobileOpen(false)}><X size={22}/></button></div>
    <nav>
      <p className="nav-label">MENU PRINCIPAL</p>
      {roleNav[user.role].map(([name, Icon]) => <button key={name} onClick={() => { setActive(name); setMobileOpen(false); }} className={active === name ? 'active' : ''}><Icon size={19}/><span>{name}</span>{name === 'Mensagens' && unread.length>0 && <b className="unread">{unread.length}</b>}</button>)}
      <p className="nav-label second">GESTÃO</p>
      {user.role==='SUPER_ADMIN'&&<button onClick={() => setActive('Configurações')} className={active === 'Configurações' ? 'active' : ''}><Settings size={19}/><span>Configurações</span></button>}
      {['SUPER_ADMIN','MANAGER'].includes(user.role)&&<button onClick={() => setActive('Auditoria')} className={active === 'Auditoria' ? 'active' : ''}><ShieldCheck size={19}/><span>Auditoria</span></button>}
    </nav>
    <div className="sidebar-help"><div className="help-icon"><CircleHelp size={19}/></div><div><b>Precisa de ajuda?</b><span>Fale com o suporte</span></div><ChevronRight size={17}/></div>
    <button className="profile" onClick={onLogout} title="Sair da plataforma"><div className="avatar avatar-main">{user.name.split(' ').map(p=>p[0]).slice(0,2).join('')}</div><div><b>{user.name}</b><span>{({SUPER_ADMIN:'SuperAdmin',MANAGER:'Gerente',SUPERVISOR:'Supervisor',SELLER:'Vendedor'})[user.role]}</span></div><MoreHorizontal size={20}/></button>
  </aside>;

  if (active !== 'Visão geral') return <div className="app-shell">
    {sidebar}{mobileOpen && <div className="scrim" onClick={() => setMobileOpen(false)}/>}
    <main className="content"><header className="topbar"><button className="hamburger" onClick={() => setMobileOpen(true)}><Menu size={23}/></button><div className="crumb"><span>RV Digital</span><ChevronRight size={16}/><b>{active}</b></div><div className="top-actions"><button className="icon-button" onClick={() => setNotice(!notice)}><Bell size={20}/>{unread.length>0&&<i/>}</button><button className="profile-mini" onClick={onLogout}><div className="avatar avatar-main">{user.name.slice(0,2).toUpperCase()}</div><ChevronDown size={16}/></button></div></header>
      <section className="page-heading"><div><p className="eyebrow">MÓDULO OPERACIONAL</p><h1>{active}</h1><p className="subtitle">Informações protegidas pelas permissões do seu perfil.</p></div></section>
      <ModulePage active={active} user={user} dashboard={dashboard} onImport={()=>setModal('upload')}/>
    </main>{modal && <Modal type={modal} close={()=>setModal(null)}/>}</div>;

  return <div className="app-shell">
    {sidebar}
    {mobileOpen && <div className="scrim" onClick={() => setMobileOpen(false)}/>} 
    <main className="content">
      <header className="topbar">
        <button className="hamburger" onClick={() => setMobileOpen(true)}><Menu size={23}/></button>
        <div className="crumb"><span>RV Digital</span><ChevronRight size={16}/><b>{active}</b></div>
        <div className="top-actions"><button className="icon-button" onClick={() => setNotice(!notice)}><Bell size={20}/>{unread.length>0&&<i/>}</button><button className="profile-mini" onClick={onLogout} title="Sair"><div className="avatar avatar-main">{user.name.slice(0,2).toUpperCase()}</div><ChevronDown size={16}/></button></div>
      </header>
      {notice && <div className="notification-pop"><b>{unread.length} atualização(ões) não lida(s)</b>{notifications.slice(0,4).map(item=><span key={item.id}>{item.title}{item.body?`: ${item.body}`:''}</span>)}{!notifications.length&&<span>Nenhuma notificação recente.</span>}</div>}
      <section className="page-heading"><div><p className="eyebrow">PAINEL {user.role === 'SELLER' ? 'INDIVIDUAL' : 'GERENCIAL'}</p><h1>Olá, {user.name.split(' ')[0]}</h1><p className="subtitle">Acompanhe o desempenho da sua operação em tempo real.</p></div><div className="heading-actions"><label className="filter-button"><CalendarDays size={17}/><select value={periodId} onChange={event=>{setPeriodId(event.target.value);refresh(event.target.value);}}>{periods.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><ChevronDown size={16}/></label>{['SUPER_ADMIN','MANAGER'].includes(user.role) && <button className="primary-button" onClick={() => setModal('upload')}><UploadCloud size={18}/>Importar resultados</button>}</div></section>

      {loadError && <div className="api-error">Não foi possível atualizar os dados: {loadError} <button onClick={refresh}>Tentar novamente</button></div>}

      <section className="kpi-grid">
        <Kpi icon={<Target size={21}/>} label="METAS DO PERÍODO" value={dashboard?.summary?.goalCount || 0} detail={`${dashboard?.summary?.sellerCount || 0} vendedores acompanhados`} tone="blue" />
        <Kpi icon={<Gauge size={21}/>} label="REALIZADO CONSOLIDADO" value={accomplished.toLocaleString('pt-BR')} detail="Soma dos resultados vinculados às metas" tone="purple" />
        <Kpi icon={<CheckCircle2 size={21}/>} label="ATINGIMENTO MÉDIO" value={pct(achievement)} detail={total ? `${Math.max(0,100-achievement).toLocaleString('pt-BR',{maximumFractionDigits:1})}% para atingir a média esperada` : 'Cadastre metas para iniciar o acompanhamento'} tone="teal" progress={achievement} />
        <Kpi icon={<CalendarDays size={21}/>} label="DIAS RESTANTES" value={dashboard?.summary?.daysRemaining || 0} detail={remaining ? `${remaining.toLocaleString('pt-BR',{maximumFractionDigits:0})} de saldo consolidado` : 'Período sem saldo pendente'} tone="orange" />
      </section>

      <section className="insight-card"><div className="insight-icon"><AlertTriangle size={22}/></div><div><b>Foco do dia</b><p>{dashboard?.focus ? <><strong>{dashboard.focus.name}</strong> está em {pct(Number(dashboard.focus.achievement))}, com {dashboard.focus.riskCount} vendedor(es) em risco.</> : 'Ainda não há metas e resultados suficientes para gerar uma prioridade operacional.'}</p></div><button onClick={() => setActive('Ações')}>Ver ações <ArrowUpRight size={16}/></button></section>

      <section className="dashboard-grid">
        <article className="panel performance-panel"><PanelTitle title="Evolução do atingimento" desc="Média acumulada das metas comparáveis"/><div className="chart-legend"><span><i className="legend achieved"></i>Atingimento</span><span><i className="legend target"></i>Referência de 100%</span></div><PerformanceChart points={dashboard?.trend||[]}/></article>
        <article className="panel goal-panel"><PanelTitle title="Projeção de fechamento" desc="Com base no ritmo atual"/><div className="donut-wrap"><Donut percentage={Math.round(achievement)}/><div className="projection-copy"><span>PROJEÇÃO</span><b>{pct(Number(dashboard?.summary?.projectedAchievement||0))}</b><p>{dashboard?.summary?.daysRemaining || 0} dias restantes</p></div></div><div className="projection-note"><CheckCircle2 size={16}/><span>{total ? <>O ritmo atual projeta <b>{pct(Number(dashboard?.summary?.projectedAchievement||0))} de atingimento médio.</b></> : 'A projeção será calculada após o cadastro das metas.'}</span></div></article>
      </section>

      <section className="section-heading"><div><h2>Desempenho das mesas</h2><p>Visão consolidada por equipe de supervisão</p></div><button className="text-button" onClick={() => setModal('teams')}>Ver todas as mesas <ChevronRight size={17}/></button></section>
      <section className="teams-grid">{displayTeams.map(team => <TeamCard key={team.name} team={team} onClick={() => setModal('team-' + team.name)} />)}{!displayTeams.length&&<DashboardEmpty icon={<Building2 size={26}/>} title="Nenhuma mesa com metas" text="As equipes aparecerão aqui assim que as metas do período forem cadastradas."/>}</section>

      <section className="bottom-grid">
        <article className="panel ranking-panel"><PanelTitle title="Ranking de vendedores" desc="Média de atingimento das metas"/><div className="ranking-list">{displayRanking.map((person, index) => <div className="rank-row" key={person.name}><span className={`rank ${index < 3 ? 'top' : ''}`}>{String(index + 1).padStart(2,'0')}</span><div className={`avatar avatar-${person.tone}`}>{person.initials}</div><div className="rank-name"><b>{person.name}</b><span>{person.team}</span></div><div className="rank-score"><b>{person.percent}%</b><div className="mini-bar"><i style={{ width: `${Math.min(person.percent,100)}%` }}></i></div></div></div>)}{!displayRanking.length&&<DashboardEmpty icon={<Trophy size={24}/>} title="Ranking aguardando dados" text="Cadastre metas e resultados para comparar o desempenho."/>}</div></article>
        <article className="panel activity-panel"><PanelTitle title="Atividades recentes" desc="Eventos registrados na operação"/><div className="activity-list">{(dashboard?.activity||[]).map((item,index) => <div className="activity" key={`${item.created_at}-${index}`}><div className="activity-icon goal"><ClipboardList size={17}/></div><div><b>{activityLabel(item.action,item.entity)}</b><p>{item.user_name||'Sistema'}</p><span>{new Date(item.created_at).toLocaleString('pt-BR')}</span></div></div>)}{!dashboard?.activity?.length&&<DashboardEmpty icon={<ShieldCheck size={24}/>} title="Sem atividade recente" text="As alterações auditadas aparecerão aqui."/>}</div></article>
      </section>
    </main>
    {modal && <Modal type={modal} close={() => setModal(null)} />}
  </div>;
}

function Kpi({icon, label, value, detail, tone, progress}) { return <article className={`kpi kpi-${tone}`}><div className="kpi-icon">{icon}</div><div className="kpi-label">{label}</div><strong>{value}</strong>{progress ? <div className="kpi-progress"><i style={{width: `${Math.min(progress, 100)}%`}}></i></div> : null}<p>{detail}</p></article> }
function PanelTitle({title, desc, action}) { return <div className="panel-title"><div><h3>{title}</h3><p>{desc}</p></div>{action && <button>{action}<ChevronRight size={16}/></button>}</div> }
function PerformanceChart({points}) { if(!points.length)return <DashboardEmpty icon={<BarChart3 size={26}/>} title="Evolução aguardando resultados" text="A série diária será formada com os lançamentos e importações do período."/>;const values=points.map(point=>Math.min(150,Number(point.achievement||0)));const path=values.map((value,index)=>`${index?'L':'M'} ${(index/Math.max(1,values.length-1))*100} ${105-value/1.5}`).join(' ');return <div className="chart"><div className="y-axis"><span>150%</span><span>112%</span><span>75%</span><span>37%</span><span>0%</span></div><div className="chart-area"><div className="gridlines">{[0,1,2,3,4].map(item=><i key={item}/>)}</div><svg viewBox="0 0 100 110" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#4b99ee" stopOpacity=".28"/><stop offset="1" stopColor="#4b99ee" stopOpacity="0"/></linearGradient></defs><path d={`${path} L 100 110 L 0 110 Z`} fill="url(#area)"/><path d="M 0 38.3 L 100 38.3" fill="none" stroke="#9ba6bd" strokeWidth="1.2" strokeDasharray="3 2"/><path d={path} fill="none" stroke="#2786e8" strokeWidth="2"/></svg><div className="x-axis">{points.slice(-6).map(point=><span key={point.date}>{new Date(`${point.date}T12:00:00`).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}</span>)}</div></div></div> }
function Donut({percentage}) { return <div className="donut" style={{'--percentage': percentage}}><div><b>{percentage}%</b><span>ATINGIMENTO</span></div></div> }
function TeamCard({team,onClick}) { const percent=Math.round(Number(team.achievement||0));return <article className="team-card" onClick={onClick}><div className="team-card-top"><div className="team-ident"><div className="team-color" style={{background:team.color}}></div><div><b>{team.name}</b><span>{team.lead}</span></div></div><button><MoreHorizontal size={19}/></button></div><div className="team-numbers"><div><span>METAS</span><b>{team.target.toLocaleString('pt-BR')}</b></div><div><span>REALIZADO</span><b>{team.achieved.toLocaleString('pt-BR')}</b></div></div><div className="team-progress"><div><b className={progressClass(percent)}>{percent}%</b><span>{team.riskCount||0} <small>em risco</small></span></div><div className="progress-line"><i className={progressClass(percent)} style={{width: `${Math.min(percent,100)}%`}}></i></div></div></article> }
function DashboardEmpty({icon,title,text}) { return <div className="dashboard-empty">{icon}<b>{title}</b><span>{text}</span></div> }
function activityLabel(action,entity) { const verbs={CREATE:'Criado',UPDATE:'Atualizado',UPSERT:'Resultado atualizado',IMPORT:'Importação concluída',LOGIN:'Acesso registrado',DISTRIBUTE:'Ação distribuída',CHANGE_PASSWORD:'Senha alterada'};return `${verbs[action]||action} · ${entity}`; }
function Modal({type,close}) { const team = type.startsWith('team-'); return <div className="modal-backdrop" onMouseDown={close}><div className="modal" onMouseDown={e=>e.stopPropagation()}><button className="modal-close" onClick={close}><X size={20}/></button>{type === 'upload' ? <ImportWorkflow close={close}/> : <><div className="modal-icon"><Target size={25}/></div><h2>{team ? type.replace('team-', '') : 'Plano de ação da operação'}</h2><p>{team ? 'Confira os indicadores prioritários e o desempenho da mesa.' : 'Acelere os resultados priorizando as equipes com maior risco de projeção.'}</p><div className="modal-info"><CheckCircle2 size={19}/><div><b>Próxima ação recomendada</b><span>Concentre as ações de hoje nos indicadores Vivo e Cadastro.</span></div></div><button className="primary-button modal-primary" onClick={close}>Entendi</button></>}</div></div> }
function ImportWorkflow({close}) { const fileInput=useRef(null); const [preview,setPreview]=useState(null); const [periods,setPeriods]=useState([]); const [periodId,setPeriodId]=useState(''); const [error,setError]=useState(''); const [busy,setBusy]=useState(false); useEffect(()=>{api('/periods').then(data=>{setPeriods(data.items);setPeriodId(data.items.find(p=>p.status==='OPEN')?.id||data.items[0]?.id||'');}).catch(reason=>setError(reason.message));},[]); const select=async file=>{if(!file)return;setBusy(true);setError('');try{const body=new FormData();body.append('file',file);setPreview(await api('/imports/preview',{method:'POST',body}));}catch(reason){setError(reason.message)}finally{setBusy(false)}}; const confirm=async()=>{setBusy(true);try{const data=await api(`/imports/${preview.previewId}/confirm`,{method:'POST',body:JSON.stringify({periodId})});alert(`Importação concluída: ${data.item.success_rows} registros processados.`);close();}catch(reason){setError(reason.message)}finally{setBusy(false)}}; return <><div className="modal-icon"><UploadCloud size={25}/></div><h2>{preview?'Validar importação':'Importar resultados'}</h2><p>{preview?`${preview.totalRows} linhas encontradas. Confira o mapeamento antes de confirmar.`:'Envie uma planilha Excel ou CSV. Vamos validar os dados antes de atualizar o dashboard.'}</p>{!preview?<><input ref={fileInput} className="file-input" type="file" accept=".xlsx,.xls,.csv" onChange={e=>select(e.target.files[0])}/><div className="drop-zone" onClick={()=>fileInput.current?.click()}><FileSpreadsheet size={32}/><b>{busy?'Lendo arquivo...':'Arraste seu arquivo aqui'}</b><span>ou clique para selecionar · .xlsx, .xls, .csv</span><button type="button">Selecionar arquivo</button></div></>:<div className="import-preview"><label>Período<select value={periodId} onChange={e=>setPeriodId(e.target.value)}>{periods.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><div className="mapping-list">{Object.entries(preview.mapping).map(([source,target])=><span key={source}><b>{source}</b><ChevronRight size={13}/><em>{target||'Não mapeado'}</em></span>)}</div>{preview.errors.length>0&&<p className="form-error">{preview.errors.length} inconsistência(s) identificada(s). Corrija a planilha ou confirme apenas os registros válidos.</p>}</div>} {error&&<p className="form-error">{error}</p>}<div className="modal-foot"><span>{preview?'Dados serão registrados em auditoria.':'As colunas serão mapeadas automaticamente.'}</span>{preview&&<button className="primary-button" disabled={busy||!periodId} onClick={confirm}>{busy?'Processando...':'Confirmar importação'}</button>}</div></> }

createRoot(document.getElementById('root')).render(<App/>);
